async function openMail(box='inbox'){
 const d=await request(`/api/players/${state.playerId}/mail?box=${box}`);
 const rows=(d.messages||[]).map(m=>`<button class="function-box mail-open" data-id="${m.id}"><b>${esc(box==='sent'?`To: ${m.recipient}`:`${m.read?'':'● '}${m.sender}`)}</b><br>${esc(m.subject)}<br><small>${new Date(m.timestamp).toLocaleString()}</small></button>`).join('')||'<p>No messages.</p>';
 showModal(`<h2>Mail</h2><div class="building-tabs"><button class="action-btn mail-box" data-box="inbox">Inbox</button><button class="action-btn mail-box" data-box="sent">Sent</button><button class="action-btn" id="mailCompose">Compose</button></div>${rows}`);
 document.querySelectorAll('.mail-box').forEach(b=>b.onclick=()=>openMail(b.dataset.box));
 document.querySelectorAll('.mail-open').forEach(b=>b.onclick=()=>openMailMessage(Number(b.dataset.id),box));
 $('mailCompose').onclick=()=>composeMail();
}
async function openMailMessage(id,box='inbox'){
 const m=await request(`/api/players/${state.playerId}/mail/${id}`);
 showModal(`<h2>${esc(m.subject)}</h2><p><b>From:</b> ${esc(m.sender)}<br><b>To:</b> ${esc(m.recipient)}<br><b>Time:</b> ${new Date(m.timestamp).toLocaleString()}</p><div class="function-box mail-body">${esc(m.body).replaceAll('\n','<br>')}</div><div class="modal-actions">${m.sender_player_id&&m.recipient_player_id===state.playerId?'<button class="action-btn" id="mailReply">Reply</button>':''}<button class="action-btn danger" id="mailDelete">Delete</button><button class="action-btn" id="mailBack">Back</button></div>`);
 if($('mailReply'))$('mailReply').onclick=()=>composeMail(m.sender,m.subject.startsWith('Re:')?m.subject:`Re: ${m.subject}`,id);
 $('mailDelete').onclick=async()=>{await request(`/api/players/${state.playerId}/mail/${id}?box=${box}`,{method:'DELETE'});openMail(box)};
 $('mailBack').onclick=()=>openMail(box);
}
function composeMail(recipient='',subject='',replyId=null){
 showModal(`<h2>${replyId?'Reply':'Compose Mail'}</h2><label>Recipient<input id="mailRecipient" maxlength="64" value="${esc(recipient)}" ${replyId?'readonly':''}></label><div id="mailRecipientMatches"></div><label>Subject<input id="mailSubject" maxlength="120" value="${esc(subject)}"></label><label>Message<textarea id="mailBody" maxlength="5000" rows="10"></textarea></label><button class="action-btn" id="mailSend">Send</button>`);
 let timer=null;$('mailRecipient').oninput=()=>{clearTimeout(timer);timer=setTimeout(async()=>{const q=$('mailRecipient').value.trim();if(q.length<2)return $('mailRecipientMatches').innerHTML='';const d=await request(`/api/players/${state.playerId}/mail/recipients?q=${encodeURIComponent(q)}`);$('mailRecipientMatches').innerHTML=d.recipients.map(x=>`<button class="action-btn recipient-pick" data-name="${esc(x.name)}">${esc(x.name)}</button>`).join('');document.querySelectorAll('.recipient-pick').forEach(b=>b.onclick=()=>{$('mailRecipient').value=b.dataset.name;$('mailRecipientMatches').innerHTML=''})},250)};
 $('mailSend').onclick=async()=>{await request(`/api/players/${state.playerId}/mail`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({recipient:$('mailRecipient').value,subject:$('mailSubject').value,body:$('mailBody').value,idempotency_key:crypto.randomUUID(),reply_to_mail_id:replyId})});showNotice('Mail sent.');openMail('sent')};
}
document.addEventListener('DOMContentLoaded',()=>{const b=$('mailButton');if(b)b.onclick=()=>openMail()});

