let chatPoll=null,chatChannel='WORLD',chatLast=0;
async function openChat(channel='WORLD'){
 chatChannel=channel;chatLast=0;if(chatPoll)clearInterval(chatPoll);
 showModal(`<h2>Chat</h2><div class="building-tabs"><button class="action-btn chat-tab" data-c="WORLD">World</button><button class="action-btn chat-tab" data-c="ALLIANCE">Alliance</button><button class="action-btn chat-tab" data-c="WHISPER">Whisper</button></div><div id="chatMessages" class="chat-messages"></div><div id="whisperRecipient" class="${channel==='WHISPER'?'':'hidden'}"><label>Whisper to <input id="chatRecipient" maxlength="64"></label></div><textarea id="chatBody" maxlength="500" rows="3"></textarea><button class="action-btn" id="chatSend">Send</button>`);
 document.querySelectorAll('.chat-tab').forEach(b=>b.onclick=()=>openChat(b.dataset.c));
 const poll=async()=>{try{const d=await request(`/api/players/${state.playerId}/chat?channel=${chatChannel}&since_id=${chatLast}`);for(const m of d.messages){chatLast=Math.max(chatLast,m.id);const div=document.createElement('div');div.className='chat-line';div.innerHTML=`<b>${esc(m.sender)}</b>${m.recipient?` → ${esc(m.recipient)}`:''}: ${esc(m.body)} <small>${new Date(m.timestamp).toLocaleTimeString()}</small>`;$('chatMessages')?.appendChild(div)}if($('chatMessages'))$('chatMessages').scrollTop=$('chatMessages').scrollHeight}catch(e){}};
 await poll();chatPoll=setInterval(poll,1500);
 $('chatSend').onclick=async()=>{await request(`/api/players/${state.playerId}/chat`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({channel:chatChannel,body:$('chatBody').value,recipient:chatChannel==='WHISPER'?$('chatRecipient').value:null})});$('chatBody').value='';await poll()};
}
document.addEventListener('DOMContentLoaded',()=>{const b=$('chatButton');if(b)b.onclick=()=>openChat()});

