async function refreshBeginnerProtection(){
 if(!state.playerId)return;
 try{
  const bp=await request(`/api/players/${state.playerId}/beginner-protection`);
  const el=$('beginnerProtection');if(!el)return;
  if(!bp.active){el.textContent='BP Ended';el.title=`Beginner Protection ended: ${bp.end_reason||'expired'}`;return;}
  const d=Math.floor(bp.seconds_remaining/86400),h=Math.floor((bp.seconds_remaining%86400)/3600),m=Math.floor((bp.seconds_remaining%3600)/60);
  el.textContent=`BP ${d}d ${h}h ${m}m`;el.title='Beginner Protection active. Ends after 7 days or when any Town Hall reaches level 5.';
 }catch(e){}
}
document.addEventListener('DOMContentLoaded',()=>{setTimeout(refreshBeginnerProtection,250);setInterval(refreshBeginnerProtection,60000)});

function renderClassicChrome(){
 if(!state.city||!state.player)return;
 const cities=state.cities||[];
 const rail=$('cityRail');if(rail){rail.innerHTML=cities.map(c=>`<button class="city-tab ${c.id===state.city.id?'active':''}" data-city="${c.id}"><b>${esc(c.name)}</b><small>(${c.x}, ${c.y})</small></button>`).join('');rail.querySelectorAll('.city-tab').forEach(b=>b.onclick=()=>selectCity(+b.dataset.city))}
 const c=state.city,p=state.player,box=$('rightCitySummary');if(box)box.innerHTML=[
 ['Coordinates',`(${c.coordinates.x}, ${c.coordinates.y})`],['Population',`${fmt(c.population.total)} / ${fmt(c.population.idle)} idle`],['Gold',fmt(c.economy.gold)],['Tax',`${c.economy.tax_rate}%`],['Loyalty',c.economy.loyalty],['Grievance',c.economy.grievance],['Prestige',fmt(p.prestige)],['Honor',fmt(p.honor)],['Title',p.title_rank_key||'—']
 ].map(([k,v])=>`<div class="city-summary-row"><span>${k}</span><b>${v}</b></div>`).join('');
}
const __classicRenderHUD=renderHUD;renderHUD=function(){__classicRenderHUD();renderClassicChrome()};

