const __uiSpecificBuilding=openBuilding;
openBuilding=async function(building){
 if(building.definition_key==='inn')return openInn(building);
 if(building.definition_key==='marketplace')return openMarketplace(building);
 if(building.definition_key==='embassy')return openEmbassy(building);
 if(building.definition_key==='cottage')return openCottage(building);
 return __uiSpecificBuilding(building)
};

