 if(!p){showNotice('Build a Rally Spot to dispatch troops.');return}
 await openRallySpot(p.building);$('marchX').value=x;$('marchY').value=y;
 const wanted=String(mission||'').toUpperCase();if([...$('marchMission').options].some(o=>o.value===wanted||o.text===wanted))$('marchMission').value=wanted;
